package com.rnd.app.service;
import com.fasterxml.jackson.databind.ObjectMapper; import com.rnd.app.dto.*; import com.rnd.app.entity.ExportJob; import com.rnd.app.repository.ExportJobRepository; import com.rnd.app.util.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.io.TempDir; import org.mockito.*; import org.springframework.data.domain.*; import org.springframework.test.util.ReflectionTestUtils; import java.nio.file.*; import java.util.*; import java.util.zip.ZipFile; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class ExportServiceTest { @TempDir Path dir; ExportJobRepository jobs=mock(ExportJobRepository.class);WorkItemService workItems=mock(WorkItemService.class);ExportService service;
 @BeforeEach void init(){service=new ExportService(jobs,workItems,new ObjectMapper());ReflectionTestUtils.setField(service,"exportPath",dir.toString());when(jobs.save(any())).thenAnswer(i->{ExportJob j=i.getArgument(0);if(j.getId()==null)j.setId(7L);return j;});}
 @Test void createsReadableXlsxWithRequestedColumns()throws Exception{WorkItemDto item=WorkItemDto.builder().id("A").title("标题").status("处理中");when(workItems.search(anyLong(),any(),any(),any(),any(),any(),any(),any(),any(),any(),any(),any(),any(),any(),anyLong(),any())).thenReturn(new PageImpl<>(List.of(item)));ExportWorkItemsRequest r=new ExportWorkItemsRequest();r.setColumns(List.of("status"));ExportJobDto out=service.create(1L,2L,r);assertEquals("READY",out.getStatus());Path file=dir.resolve(out.getFileName());assertTrue(Files.exists(file));try(ZipFile zip=new ZipFile(file.toFile())){assertNotNull(zip.getEntry("xl/worksheets/sheet1.xml"));}}
 @Test void refusesExportWhenMoreThanTenThousandItemsMatch()throws Exception{when(workItems.search(anyLong(),any(),any(),any(),any(),any(),any(),any(),any(),any(),any(),any(),any(),any(),anyLong(),any())).thenReturn(new PageImpl<>(List.of(),PageRequest.of(0,10000),10001));ExportWorkItemsRequest r=new ExportWorkItemsRequest();BusinessException error=assertThrows(BusinessException.class,()->service.create(1L,2L,r));assertEquals(ErrorCode.BAD_REQUEST,error.getErrorCode());try(var files=Files.list(dir)){assertEquals(0,files.count());}}
}
